from typing import List

class Solution:
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        parent = [-1] * n

        for i in range(n):
            left = leftChild[i]
            right = rightChild[i]

            if left != -1:
                if parent[left] != -1:
                    return False
                parent[left] = i

            if right != -1:
                if parent[right] != -1:
                    return False
                parent[right] = i

        root_count = 0
        root = -1
        for i in range(n):
            if parent[i] == -1:
                root_count += 1
                root = i

        if root_count != 1:
            return False

        visited = [False] * n
        stack = [root]

        while stack:
            node = stack.pop()
            if visited[node]:
                return False
            visited[node] = True

            left = leftChild[node]
            right = rightChild[node]

            if left != -1:
                stack.append(left)
            if right != -1:
                stack.append(right)

        return all(visited)
